package com.financecoach.controller;
import com.financecoach.dto.*;import com.financecoach.security.UserPrincipal;import com.financecoach.service.CoachService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/coach") public class CoachController {private final CoachService service;public CoachController(CoachService service){this.service=service;}@PostMapping("/simulate")public ResponseEntity<SimulationResponse> simulate(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody SimulationRequest r){return ResponseEntity.ok(service.simulate(p.getId(),r));}@PostMapping("/chat")public ResponseEntity<CoachResponse> chat(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody CoachRequest r){return ResponseEntity.ok(service.chat(p.getId(),r.text()));}}
